Read file card.ts, lines 1-29
1: import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
2: import { dirname } from 'node:path';
3: 
4: try {
5:   const [action, flag, configPath, write, ...extra] = process.argv.slice(2);
6:   if (!['generate', 'verify'].includes(action ?? '') || flag !== '--config' || !configPath ||
7:       extra.length || (write !== undefined && (action !== 'generate' || write !== '--write'))) {
8:     throw new Error('usage: bun card.ts <generate|verify> --config <path> [--write]');
9:   }
10:   const config: unknown = JSON.parse(readFileSync(configPath, 'utf8'));
11:   if (!config || typeof config !== 'object' || !('prefix' in config) || typeof config.prefix !== 'string' ||
12:       !('version' in config) || typeof config.version !== 'string' ||
13:       !('output' in config) || typeof config.output !== 'string') throw new Error('invalid card config');
14:   const label = `${config.prefix}${config.version}`;
15:   const expected = `${label}\n`;
16:   if (action === 'verify') {
17:     if (readFileSync(config.output, 'utf8') !== expected) throw new Error(`card differs: ${config.output}`);
18:     console.log(`verified ${config.output}: ${label}`);
19:   } else if (write === '--write') {
20:     mkdirSync(dirname(config.output), { recursive: true });
21:     writeFileSync(config.output, expected);
22:     console.log(`wrote ${config.output}: ${label}`);
23:   } else {
24:     console.log(`dry run ${config.output}: ${label}`);
25:   }
26: } catch (error) {
27:   console.error(error instanceof Error ? error.message : String(error));
28:   process.exitCode = 1;
29: }
